css:
.brandsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2c241c;
    background: radial-gradient(circle at 16% 0%, #f3ead9 0%, #ece0c8 55%, #e3d4b6 100%);
    border-radius: 18px;
}

.brandsim-container * {
    box-sizing: border-box;
}

.brandsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #3d2b1c 0%, #5a4129 50%, #2f5d3a 100%);
    color: #f6efe2;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #4a3624;
    box-shadow: 0 12px 34px rgba(60, 40, 22, 0.35);
}

.brandsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fdf8ee;
}

.brandsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #8fd6a4;
    background: rgba(143, 214, 164, 0.14);
    border: 1px solid rgba(143, 214, 164, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.brandsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6dcc8;
}

.brandsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5740;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.brandsim-period-counter #currentDay,
.brandsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f7d4a;
}

.brandsim-round-name {
    background: rgba(47, 125, 74, 0.14);
    color: #2f7d4a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.brandsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8521f;
    background: rgba(168, 82, 31, 0.12);
    border: 1px solid rgba(168, 82, 31, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.brandsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.brandsim-status-card {
    background: linear-gradient(160deg, #fffaf0 0%, #f6edda 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddcca8;
    box-shadow: 0 6px 18px rgba(90, 65, 41, 0.12);
    border-top: 4px solid #b08a4f;
}

.brandsim-card-aware { border-top-color: #c98a3c; }
.brandsim-card-equity { border-top-color: #2f7d4a; }
.brandsim-card-sustain { border-top-color: #4f9d6b; }
.brandsim-card-margin { border-top-color: #6b8f1e; }

.brandsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7456;
}

.brandsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2c241c;
    font-variant-numeric: tabular-nums;
}

.brandsim-card-aware .brandsim-value { color: #b9772c; }
.brandsim-card-equity .brandsim-value { color: #2f7d4a; }
.brandsim-card-sustain .brandsim-value { color: #4f9d6b; }
.brandsim-card-margin .brandsim-value { color: #5d7d18; }

.brandsim-sublabel {
    font-size: 0.76rem;
    color: #9a8568;
    line-height: 1.35;
}

.brandsim-margin-breach { border-top-color: #c0392b; }
.brandsim-margin-breach .brandsim-value { color: #c0392b; }
.brandsim-margin-safe { border-top-color: #6b8f1e; }

.brandsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffaf0;
    border: 1px solid #ddcca8;
    color: #4a3a26;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.brandsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #2f7d4a;
}

.brandsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #fffaf0 0%, #f4ead4 100%);
    border-left: 5px solid #2f7d4a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(90, 65, 41, 0.10);
}

.brandsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.brandsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2c241c;
    margin-bottom: 6px;
}

.brandsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3a26;
}

.brandsim-briefing-text strong { color: #2f7d4a; }
.brandsim-briefing-text em { color: #a8521f; font-style: italic; }

.brandsim-controls {
    background: linear-gradient(160deg, #fffaf0 0%, #f6edda 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddcca8;
    box-shadow: 0 6px 18px rgba(90, 65, 41, 0.10);
}

.brandsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2c241c;
    border-bottom: 2px solid #e2d2af;
    padding-bottom: 8px;
}

.brandsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a3a26;
    margin: 14px 0 6px;
}

.brandsim-container select,
.brandsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbb78c;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2c241c;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.brandsim-container select:focus,
.brandsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d4a;
    box-shadow: 0 0 0 3px rgba(47, 125, 74, 0.18);
}

.brandsim-container select option {
    background-color: #fffdf8;
    color: #2c241c;
}

.brandsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d4a;
}

.brandsim-range-readout,
.brandsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b5740;
    margin-top: 4px;
}

.brandsim-range-readout span:last-child,
.brandsim-alloc-readout span:nth-child(2) {
    color: #2f7d4a;
    font-weight: 800;
}

.brandsim-hint {
    font-size: 0.8rem;
    color: #9a8568;
    margin-top: 4px;
    line-height: 1.4;
}

.brandsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.brandsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fffdf8;
    border: 1px solid #e2d2af;
    border-radius: 9px;
    padding: 8px 12px;
}

.brandsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a3a26;
}

.brandsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.brandsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.brandsim-container .btn-primary {
    background: linear-gradient(135deg, #1f6b39 0%, #3fa163 100%);
    border: none;
    color: #f4fff7;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(31, 107, 57, 0.35);
}

.brandsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.brandsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbb78c;
    color: #6b5740;
    background: transparent;
}

.brandsim-coach {
    background: linear-gradient(160deg, #2f3a2c 0%, #243a2a 100%);
    color: #e6f0e2;
    border: 1px solid #3a5240;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(40, 50, 36, 0.30);
}

.brandsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fd6a4;
    margin-bottom: 8px;
}

.brandsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.brandsim-coach-body strong { color: #8fd6a4; }
.brandsim-coach-body em { color: #f0b46b; font-style: italic; }

.brandsim-history,
.brandsim-chart {
    background: linear-gradient(160deg, #fffaf0 0%, #f6edda 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddcca8;
    box-shadow: 0 6px 18px rgba(90, 65, 41, 0.10);
}

.brandsim-history h3,
.brandsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2c241c;
}

.brandsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3a26;
}

.brandsim-container table#usfHistoryTable th {
    background: #f1e6cd;
    color: #2f7d4a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddcca8;
}

.brandsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece0c8;
    color: #4a3a26;
}

.brandsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf3e3;
}

.brandsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .brandsim-container {
        padding: 14px;
    }
    .brandsim-header h1 {
        font-size: 1.7rem;
    }
    .brandsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .brandsim-value {
        font-size: 2rem;
    }
    .brandsim-clock {
        margin-left: 0;
    }
    .brandsim-period-counter {
        font-size: 0.88rem;
    }
    .brandsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .brandsim-alloc-row {
        flex-wrap: wrap;
    }
    .brandsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .brandsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================================
   v1.1.0 — Completion debrief (formatCompletionMessage). Append-only, namespaced
   .bb-cm-* so it cannot collide with the base engine or the .brandsim-* view.
   Coffee/sustainability palette matched to the header (browns + greens, cream).
   ============================================================================ */
.bb-cm {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2c241c;
    text-align: left;
    max-width: 760px;
    margin: 0 auto;
}
.bb-cm-incomplete { text-align: center; color: #6b5a44; font-size: 1rem; padding: 18px; }
.bb-cm-head {
    display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px;
    padding: 20px 22px; margin-bottom: 16px;
    background: linear-gradient(135deg, #3d2b1c 0%, #5a4129 52%, #2f5d3a 100%);
    color: #f6efe2; border-radius: 16px; border: 1px solid #4a3624;
    box-shadow: 0 10px 28px rgba(60, 40, 22, 0.30);
}
.bb-cm-score { text-align: center; padding-right: 20px; border-right: 1px solid rgba(246,239,226,0.22); }
.bb-cm-score-num { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #f7d9a3; }
.bb-cm-score-den { font-size: 1.1rem; font-weight: 600; color: #d8c3a0; margin-left: 2px; }
.bb-cm-score-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; margin-top: 8px; color: #cdbb9c; }
.bb-cm-verdict { display: flex; flex-direction: column; justify-content: center; flex: 1 1 auto; min-width: 180px; }
.bb-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: #9fd6ac; font-weight: 700; }
.bb-cm-verdict-tier { font-size: 1.55rem; font-weight: 800; letter-spacing: -0.3px; color: #fdf8ee; margin-top: 4px; }
.bb-cm-section { margin: 0 0 16px; }
.bb-cm-section-h {
    font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1.1px;
    font-weight: 700; color: #7a6547; margin-bottom: 9px;
}
.bb-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.bb-cm-chip {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 0.82rem; font-weight: 600; padding: 6px 12px; border-radius: 999px;
    border: 1px solid transparent;
}
.bb-cm-chip .bb-cm-ico { font-weight: 800; }
.bb-cm-ok  { background: #e4f1e6; color: #1f5c33; border-color: #b7dcc0; }
.bb-cm-no  { background: #f6e5e0; color: #93331f; border-color: #e3c1b7; }
.bb-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.bb-cm-kpi {
    background: #fbf6ec; border: 1px solid #e3d4b6; border-radius: 12px;
    padding: 12px 14px; text-align: center;
}
.bb-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #5a4129; line-height: 1.1; }
.bb-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #4a3a26; margin-top: 4px; }
.bb-cm-kpi-sub { font-size: 0.68rem; color: #8a7456; margin-top: 3px; }
.bb-cm-insights { margin: 0; padding-left: 20px; }
.bb-cm-insights li { font-size: 0.9rem; line-height: 1.5; color: #3f3427; margin-bottom: 7px; }
@media (max-width: 520px) {
    .bb-cm-score { border-right: none; border-bottom: 1px solid rgba(246,239,226,0.22); padding-right: 0; padding-bottom: 14px; }
    .bb-cm-head { flex-direction: column; }
}

