(function() {
    'use strict';

    class BrandAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Brand Builder`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Café Cordillera S.A.).
            this.MEDIA_BUDGET = 480;      // CRC 480M annual media budget
            this.MARGIN_FLOOR = 18;       // 18% hard contribution-margin floor
            this.START_MARGIN = 22;       // 22% pre-relaunch contribution margin
            this.START_AWARE = 31;        // 31% aided awareness (rival at 58%)
            this.START_EQUITY = 42;       // brand-equity index 42/100
            this.START_SUSTAIN = 38;      // sustainability perception, ~category average
            this.RIVAL_AWARE = 58;        // multinational rival's aided awareness

            // Concept truths.
            this.TRUE_POSITION = `core`;
            this.TRUE_CLAIM = `specific`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    aware: this.START_AWARE,       // aided brand awareness (%)
                    equity: this.START_EQUITY,     // brand-equity index (0–100)
                    sustain: this.START_SUSTAIN,   // sustainability perception (0–100)
                    margin: this.START_MARGIN,     // contribution margin (%)
                    roi: 0,                        // cumulative campaign ROI score
                    budgetUsed: 0,                 // CRC M of media budget committed
                    greenwashed: false,            // overclaim triggered a complaint
                    wastedAsset: false,            // underclaimed the true story
                    breachedFloor: false,          // margin fell below the 18% floor
                    awareHistory: [this.START_AWARE],
                    equityHistory: [this.START_EQUITY],
                    sustainHistory: [this.START_SUSTAIN],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    segment: `mass`,
                    position: `taste`,
                    proof: 50,
                    claim: `broad`,
                    proofmech: `cert`,
                    boldness: 50,
                    tv: 96,
                    digital: 96,
                    trade: 96,
                    pr: 96,
                    d2c: 96,
                    ai: `autopilot`,
                    kpi: `inflated`,
                    premium: `discount`,
                    coherence: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sg = document.getElementById(`segmentInput`);
                const po = document.getElementById(`positionInput`);
                const pf = document.getElementById(`proofInput`);
                if (sg) decisions.segment = sg.value;
                if (po) decisions.position = po.value;
                if (pf) decisions.proof = parseInt(pf.value, 10);
                if (!Number.isFinite(decisions.proof) || decisions.proof < 0 || decisions.proof > 100) {
                    warn(`warn_proof_range`); return false;
                }
            } else if (round === 2) {
                const cl = document.getElementById(`claimInput`);
                const pm = document.getElementById(`proofmechInput`);
                const bd = document.getElementById(`boldnessInput`);
                if (cl) decisions.claim = cl.value;
                if (pm) decisions.proofmech = pm.value;
                if (bd) decisions.boldness = parseInt(bd.value, 10);
                if (!Number.isFinite(decisions.boldness) || decisions.boldness < 0 || decisions.boldness > 100) {
                    warn(`warn_boldness_range`); return false;
                }
            } else if (round === 3) {
                const tv = document.getElementById(`tvInput`);
                const dg = document.getElementById(`digitalInput`);
                const tr = document.getElementById(`tradeInput`);
                const pr = document.getElementById(`prInput`);
                const dc = document.getElementById(`d2cInput`);
                const ai = document.getElementById(`aiInput`);
                if (tv) decisions.tv = parseFloat(tv.value);
                if (dg) decisions.digital = parseFloat(dg.value);
                if (tr) decisions.trade = parseFloat(tr.value);
                if (pr) decisions.pr = parseFloat(pr.value);
                if (dc) decisions.d2c = parseFloat(dc.value);
                if (ai) decisions.ai = ai.value;
                const parts = [decisions.tv, decisions.digital, decisions.trade, decisions.pr, decisions.d2c];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0));
                if (Math.abs(total - this.MEDIA_BUDGET) > 0.5) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const kp = document.getElementById(`kpiInput`);
                const pm = document.getElementById(`premiumInput`);
                const ch = document.getElementById(`coherenceInput`);
                if (kp) decisions.kpi = kp.value;
                if (pm) decisions.premium = pm.value;
                if (ch) decisions.coherence = parseInt(ch.value, 10);
                if (!Number.isFinite(decisions.coherence) || decisions.coherence < 0 || decisions.coherence > 100) {
                    warn(`warn_coherence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let awareDelta = 0, equityDelta = 0, sustainDelta = 0, marginDelta = 0, roiDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose & position — sustainability as MEANING, not garnish (Common Error 4).
                switch (d.segment) {
                    case `conscious`: equityDelta += 6; sustainDelta += 4; coachKey = `coach_r1_conscious`; break;
                    case `mass`: equityDelta -= 2; coachKey = `coach_r1_mass`; break;
                    case `price`: equityDelta -= 4; marginDelta -= 0.3; coachKey = `coach_r1_price`; break;
                    case `rivalfans`: equityDelta -= 3; coachKey = `coach_r1_rivalfans`; break;
                }

                switch (d.position) {
                    case `core`: equityDelta += 10; sustainDelta += 8; awareDelta += 2; coachKey = `coach_r1_core`; break;
                    case `taste`: sustainDelta -= 2; equityDelta += 1; coachKey = `coach_r1_taste`; break;
                    case `price`: equityDelta -= 4; sustainDelta -= 3; coachKey = `coach_r1_posprice`; break;
                    case `heritage`: equityDelta += 2; sustainDelta -= 1; break;
                }

                // Realness of the proof points the position rests on.
                const pf = d.proof / 100;
                sustainDelta += pf * 8 - 2;       // weak proof actively dents perception
                equityDelta += pf * 4;
                if (d.proof <= 25) { coachKey = `coach_r1_weakproof`; }

                summaryKey = (d.position === `core` && d.segment === `conscious`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Claim architecture — substance over signal (Common Errors 2 & 3).
                const bold = d.boldness / 100;
                // Evidence ceiling: how much of the bold claim your proof can actually back.
                let evidence = 0.4;
                if (d.proofmech === `traceability`) evidence = 0.95;
                else if (d.proofmech === `cert`) evidence = 0.65;
                else if (d.proofmech === `story`) evidence = 0.45;
                else evidence = 0.20; // none

                switch (d.claim) {
                    case `specific`:
                        // The true 100%-certified story, claimed with verifiable specifics.
                        sustainDelta += 14; equityDelta += 8; awareDelta += 4; coachKey = `coach_r2_specific`;
                        break;
                    case `broad`:
                        // Bold "eco" language moves perception fast but outruns proof.
                        sustainDelta += 10; awareDelta += 6; coachKey = `coach_r2_broad`;
                        break;
                    case `timid`:
                        // Vague, defensible — and forgettable. Wastes the real asset
                        // (Decision Tree #3: "perception moved one point").
                        sustainDelta += 1; equityDelta -= 2; ds.wastedAsset = true; coachKey = `coach_r2_timid`;
                        break;
                    case `generic`:
                        // Sustainability whispered. The category's best story, unsaid.
                        sustainDelta += 0; equityDelta -= 1; awareDelta += 2; ds.wastedAsset = true; coachKey = `coach_r2_generic`;
                        break;
                }

                switch (d.proofmech) {
                    case `traceability`: sustainDelta += 6; equityDelta += 5; break;
                    case `cert`: sustainDelta += 2; break;
                    case `story`: equityDelta += 2; sustainDelta -= 1; break;
                    case `none`: sustainDelta -= 4; break;
                }

                // Greenwashing trap: claiming far past your evidence draws a complaint.
                const overclaim = bold - evidence;
                if (overclaim > 0.20) {
                    ds.greenwashed = true;
                    const hit = Math.round(overclaim * 30);
                    sustainDelta -= hit; equityDelta -= Math.round(hit * 0.7); awareDelta -= 2;
                    coachKey = `coach_r2_greenwash`;
                } else if (bold < 0.20 && d.claim !== `specific`) {
                    // Whispered the genuine asset.
                    ds.wastedAsset = true;
                    if (coachKey === `coach_r2_broad`) coachKey = `coach_r2_underclaim`;
                } else if (d.claim === `specific` && d.proofmech === `traceability` && overclaim <= 0.05) {
                    coachKey = `coach_r2_substantiated`;
                }

                summaryKey = (d.claim === `specific` && d.proofmech === `traceability` && !ds.greenwashed) ? `sum_r2_good` :
                             (ds.greenwashed ? `sum_r2_greenwash` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate the CRC 480M across channels under the margin floor (Common Error 1).
                const tv = d.tv, dg = d.digital, tr = d.trade, pr = d.pr, dc = d.d2c;
                const B = this.MEDIA_BUDGET;
                spend = tv + dg + tr + pr + dc;

                // Reach (awareness) is TV-heavy with diminishing returns; conversion is digital/trade/D2C.
                // Equity-building is digital storytelling + influencer/PR credibility.
                awareDelta += Math.sqrt(tv / B) * 16 + Math.sqrt(dg / B) * 7 + Math.sqrt(pr / B) * 3;
                equityDelta += Math.sqrt(dg / B) * 10 + Math.sqrt(pr / B) * 9 + Math.sqrt(dc / B) * 4 - Math.sqrt(tv / B) * 2;
                sustainDelta += Math.sqrt(pr / B) * 8 + Math.sqrt(dg / B) * 5;
                // Conversion / ROI: trade & D2C convert; TV alone is vanity reach.
                roiDelta += (tr / B) * 8 + (dc / B) * 10 + (dg / B) * 6 - (tv / B) * 4;

                // Margin pressure (the 18% floor binds here). Two drains:
                //  - trade spend lifts sell-through but is booked against contribution margin;
                //  - mass-reach TV/streaming is high-cost, low-conversion brand spend, so it
                //    erodes margin without earning it back (Decision Tree #1: ~17.2% < 18%).
                marginDelta -= (tr / B) * 5.0;
                marginDelta -= (tv / B) * 6.5;
                // Over-indexing on TV: famous-but-unprofitable vanity reach.
                if (tv / B >= 0.55) {
                    awareDelta += 4;               // famous...
                    equityDelta -= 6; roiDelta -= 8; marginDelta -= 1.5; // ...but hollow & margin-breaking
                    coachKey = `coach_r3_tvheavy`;
                }

                // AI-personalization layer — disciplined co-pilot vs captain (Common Error 5).
                switch (d.ai) {
                    case `copilot`: equityDelta += 5; roiDelta += 6; awareDelta += 2; if (coachKey === `coach_default`) coachKey = `coach_r3_copilot`; break;
                    case `ignore`: roiDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r3_ignoreai`; break;
                    case `autopilot`: equityDelta -= 4; roiDelta -= 5; awareDelta -= 1; coachKey = `coach_r3_autopilot`; break;
                }

                summaryKey = (tv / B < 0.45 && (tr + dc + dg) / B >= 0.5 && d.ai === `copilot`) ? `sum_r3_good` :
                             (tv / B >= 0.55 ? `sum_r3_tvheavy` : `sum_r3_weak`);
            } else if (round === 4) {
                // Board review — honest KPI accounting + premium defense (Common Error 6 mirror).
                switch (d.kpi) {
                    case `honest`: equityDelta += 8; sustainDelta += 3; coachKey = `coach_r4_honest`; break;
                    case `inflated`:
                        // Claims that can't all be true at CRC 480M — the board sees through it.
                        equityDelta -= 6; sustainDelta -= 2; coachKey = `coach_r4_inflated`;
                        break;
                    case `vanity`: equityDelta -= 3; coachKey = `coach_r4_vanity`; break;
                }

                switch (d.premium) {
                    case `equity`: equityDelta += 6; marginDelta += 1.0; roiDelta += 4; coachKey = `coach_r4_premium`; break;
                    case `discount`: marginDelta -= 1.5; equityDelta -= 4; coachKey = `coach_r4_discount`; break;
                    case `ignore`: equityDelta -= 2; marginDelta -= 0.4; break;
                }

                const co = d.coherence / 100;
                equityDelta += co * 8 - 3;        // an incoherent system loses equity
                sustainDelta += co * 4;
                if (d.coherence >= 60 && ds.sustain >= 55 && d.kpi === `honest`) coachKey = `coach_r4_coherent`;
                else if (d.coherence <= 25) coachKey = `coach_r4_incoherent`;

                summaryKey = (d.kpi === `honest` && d.premium === `equity` && d.coherence >= 60) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: only the media budget is metered (committed in R3).
            ds.budgetUsed = Math.min(this.MEDIA_BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas with clamps. Awareness can chase but not exceed ~the rival's ceiling band.
            ds.aware = Math.max(0, Math.min(75, Math.round((ds.aware + awareDelta) * 10) / 10));
            ds.equity = Math.max(0, Math.min(100, Math.round(ds.equity + equityDelta)));
            ds.sustain = Math.max(0, Math.min(100, Math.round(ds.sustain + sustainDelta)));
            ds.margin = Math.round((ds.margin + marginDelta) * 10) / 10;
            ds.roi = Math.round((ds.roi + roiDelta) * 10) / 10;

            if (ds.margin < this.MARGIN_FLOOR) ds.breachedFloor = true;

            // v1.1.0 fix — persist the composite where the Express grading/reporting layer reads it.
            // results_utils.php express_resolveDomainScore() reads performance.overallScore first,
            // then top-level score; express_extractHistory() reads per-period
            // domainState.performance.overallScore. Previously never written → gradebook showed "-",
            // analytics blank, AGS/LTI post-back sent 0.
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            ds.awareHistory.push(ds.aware);
            ds.equityHistory.push(ds.equity);
            ds.sustainHistory.push(ds.sustain);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                score: composite,
                overallScore: composite,
                aware: ds.aware,
                awareDelta: Math.round(awareDelta * 10) / 10,
                equity: ds.equity,
                equityDelta: Math.round(equityDelta),
                sustain: ds.sustain,
                sustainDelta: Math.round(sustainDelta),
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                roi: ds.roi,
                budgetUsed: ds.budgetUsed,
                greenwashed: ds.greenwashed,
                wastedAsset: ds.wastedAsset,
                breachedFloor: ds.breachedFloor,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware CRC (millions). English "₡480M" (symbol before),
            // Spanish "480 M₡" (symbol after, comma decimal, dot thousands).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            const whole = Math.round(abs);
            if (lang === `es`) {
                return `${sign}${whole.toLocaleString(`es-ES`)} M₡`;
            }
            return `${sign}₡${whole.toLocaleString(`en-US`)}M`;
        }

        _fmtPct(v, dp) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Number(v);
            let s = (dp != null) ? n.toFixed(dp) : String(Math.round(n));
            if (lang === `es`) s = s.replace(`.`, `,`);
            return s + `%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`awareDisplay`, `domainState.aware`, (v) => self._fmtPct(Number(v), 0));
            uiManager.bind(`equityDisplay`, `domainState.equity`, (v) => Math.round(Number(v)));
            uiManager.bind(`sustainDisplay`, `domainState.sustain`, (v) => Math.round(Number(v)));
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const card = document.querySelector(`.brandsim-card-margin`);
                if (card) {
                    card.classList.toggle(`brandsim-margin-breach`, Number(v) < self.MARGIN_FLOOR);
                    card.classList.toggle(`brandsim-margin-safe`, Number(v) >= self.MARGIN_FLOOR);
                }
                return self._fmtPct(Number(v), 1);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.MEDIA_BUDGET);
            });

            // Proof-realness slider readout.
            const pf = document.getElementById(`proofInput`);
            const pfReadout = document.getElementById(`proofReadout`);
            if (pf && pfReadout) {
                pfReadout.textContent = pf.value;
                pf.addEventListener(`input`, function() { pfReadout.textContent = pf.value; });
            }

            // Boldness slider readout.
            const bd = document.getElementById(`boldnessInput`);
            const bdReadout = document.getElementById(`boldnessReadout`);
            if (bd && bdReadout) {
                bdReadout.textContent = bd.value;
                bd.addEventListener(`input`, function() { bdReadout.textContent = bd.value; });
            }

            // Media-budget live total (must hit CRC 480M).
            const allocIds = [`tvInput`, `digitalInput`, `tradeInput`, `prInput`, `d2cInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.brandsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.MEDIA_BUDGET) > 0.5) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

