        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.awareHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `Q` + i));
            return {
                brandChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.awareHistory },
                        { data: ds.equityHistory },
                        { data: ds.sustainHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite formula (was inline in getPerformanceSummary),
            // extracted so the per-period persisted score and the completion summary are
            // identical by construction.
            const aware = Math.round(ds.aware);
            const equity = Math.round(ds.equity);
            const sustain = Math.round(ds.sustain);
            const roi = ds.roi;
            const roiScore = Math.max(-15, Math.min(15, roi));
            let composite = Math.round(
                equity * 0.34 + sustain * 0.30 + aware * 0.20 + (roiScore + 15) * 0.53
            );
            if (ds.breachedFloor) composite = Math.min(composite, 45);
            if (ds.greenwashed) composite = Math.min(composite, 40);
            return composite;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const aware = Math.round(ds.aware);
            const equity = Math.round(ds.equity);
            const sustain = Math.round(ds.sustain);
            const margin = ds.margin;
            const roi = ds.roi;

            // Composite via shared helper (verbatim v1.0.0 formula) — identical to the
            // per-period persisted score by construction.
            const composite = this._composite(ds);

            const heldFloor = margin >= this.MARGIN_FLOOR;
            const equityBuilt = equity >= 60 && sustain >= 60;
            const aware50 = aware >= 50;

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_downmarket`;
            if (heldFloor && equityBuilt && aware50 && composite >= 75) tierKey = `grade_trusted`;
            else if (heldFloor && equityBuilt) tierKey = `grade_equity`;
            else if (ds.greenwashed) tierKey = `grade_greenwash`;
            else if (!heldFloor) tierKey = `grade_margin`;
            else if (ds.wastedAsset) tierKey = `grade_wasted`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (heldFloor && equityBuilt && aware50) insights.push(window.mySimulation.t(`insight_trusted`));
            else if (ds.greenwashed) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (ds.wastedAsset) insights.push(window.mySimulation.t(`insight_wasted`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!heldFloor) insights.push(window.mySimulation.t(`insight_margin`));
            else if (margin >= 20) insights.push(window.mySimulation.t(`insight_margin_strong`));
            if (roi < 0) insights.push(window.mySimulation.t(`insight_roi_negative`));
            else if (roi >= 8) insights.push(window.mySimulation.t(`insight_roi_strong`));
            if (sustain >= 65 && equity >= 60) insights.push(window.mySimulation.t(`insight_converted`));
            if (aware >= 55 && equity < 50) insights.push(window.mySimulation.t(`insight_vanity`));

            return {
                aware: aware,
                equity: equity,
                sustain: sustain,
                margin: margin,
                roi: roi,
                heldFloor: heldFloor,
                equityBuilt: equityBuilt,
                greenwashed: ds.greenwashed,
                wastedAsset: ds.wastedAsset,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="bb-cm"><p class="bb-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const self = this;
            const chip = (ok, label) => `<span class="bb-cm-chip ` + (ok ? `bb-cm-ok` : `bb-cm-no`) + `">` +
                `<span class="bb-cm-ico">` + (ok ? `\u2713` : `\u2715`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="bb-cm-kpi"><div class="bb-cm-kpi-val">` + val +
                `</div><div class="bb-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="bb-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const awareOk = s.aware >= 50, equityOk = s.equity >= 60, sustainOk = s.sustain >= 60, floorOk = !!s.heldFloor;
            const roiTxt = (s.roi > 0 ? `+` : ``) + (Math.round(s.roi * 10) / 10);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="bb-cm">` +
  `<div class="bb-cm-head">` +
    `<div class="bb-cm-score"><div class="bb-cm-score-num">` + Math.round(s.composite) +
       `<span class="bb-cm-score-den">/100</span></div>` +
       `<div class="bb-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="bb-cm-verdict"><div class="bb-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="bb-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="bb-cm-section"><div class="bb-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="bb-cm-chips">` + chip(awareOk, t(`cm_t_aware`)) + chip(equityOk, t(`cm_t_equity`)) +
      chip(sustainOk, t(`cm_t_sustain`)) + chip(floorOk, t(`cm_t_floor`)) + `</div></div>` +
  `<div class="bb-cm-section"><div class="bb-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="bb-cm-kpis">` +
      kpi(t(`aware_label`), self._fmtPct(Number(s.aware), 0), t(`aware_sub`)) +
      kpi(t(`equity_label`), Math.round(s.equity), t(`equity_sub`)) +
      kpi(t(`sustain_label`), Math.round(s.sustain), t(`sustain_sub`)) +
      kpi(t(`margin_label`), self._fmtPct(Number(s.margin), 1), t(`cm_floor_note`)) +
      kpi(t(`cm_roi`), roiTxt, ``) +
    `</div></div>` +
  (insights ? `<div class="bb-cm-section"><div class="bb-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="bb-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.breachedFloor) return window.mySimulation.t(`hint_margin`);
            if (ds.greenwashed) return window.mySimulation.t(`hint_greenwash`);
            if (ds.wastedAsset && state.currentPeriod >= 2) return window.mySimulation.t(`hint_wasted`);
            if (ds.aware >= 50 && ds.equity < 48) return window.mySimulation.t(`hint_vanity`);
            if (state.currentPeriod >= 3 && ds.sustain < 50) return window.mySimulation.t(`hint_sustain`);
            if (ds.equity >= 60 && ds.sustain >= 60 && ds.margin >= this.MARGIN_FLOOR) return window.mySimulation.t(`hint_strong`);
            return null;
        }

