        getTranslations() {
            return {
                en: {
                    grade_trusted:          `Trusted Sustainable Brand`,
                    grade_equity:           `Equity Rebuilt`,
                    grade_greenwash:        `Greenwashing Backlash`,
                    grade_margin:           `Margin Floor Breached`,
                    grade_wasted:           `Asset Wasted`,
                    grade_mixed:            `Mixed Outcome`,
                    grade_downmarket:       `Repositioned Downmarket`,
                    cm_incomplete:          `Simulation complete.`,
                    cm_score:               `Composite brand outcome`,
                    cm_verdict:             `Board verdict`,
